update competition_enterprise_rela
competition_series_id = #{competitionSeriesId}, competition_track_config_id = #{competitionTrackConfigId}, enterprise_id = #{enterpriseId}, copt_end_time = #{coptEndTime}, copt_start_time = #{coptStartTime}, spop_amount = #{spopAmount}, cooperation_type = #{cooperationType}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = version+1, del_flag = #{delFlag}, user_id = #{userId}, org_id = #{orgId},
where rela_id = #{relaId} and competition_series_id = #{competitionSeriesId}

update competition_enterprise_rela
enterprise_id = CASE
WHEN rela_id = #{item.relaId} THEN #{item.enterpriseId}
ELSE enterprise_id END,
copt_end_time = CASE
WHEN rela_id = #{item.relaId} THEN #{item.coptEndTime}
ELSE copt_end_time END,
copt_start_time = CASE
WHEN rela_id = #{item.relaId} THEN #{item.coptStartTime}
ELSE copt_start_time END,
spop_amount = CASE
WHEN rela_id = #{item.relaId} THEN #{item.spopAmount}
ELSE spop_amount END,
cooperation_type = CASE
WHEN rela_id = #{item.relaId} THEN #{item.cooperationType}
ELSE cooperation_type END,
update_time = NOW(), version = version + 1
WHERE rela_id IN
#{item.relaId}
